def decode(
    domain: str | bytes,
    *,
    uts46: bool = False,
    std3_rules: bool = False,
) -> str:
    """Decode an ASCII (A-label) domain name to its Unicode (U-label) form."""
    return idna.decode(
        domain,
        uts46=uts46,
        std3_rules=std3_rules,
    )

def main(argv: list[str] | None = None) -> int:
